commands:
$nvidiaSmiPath = 'C:\Program Files\NVIDIA Corporation\NVSMI\nvidia-smi.exe'

if (Test-Path $nvidiaSmiPath) {
    Write-Host "Found nvidia-smi.exe, setting unrestricted clock policy..." -ForegroundColor Green
    & $nvidiaSmiPath -acp 0
    Write-Host "Clock policy set successfully!" -ForegroundColor Green
} else {
    Write-Host "ERROR: nvidia-smi.exe not found at $nvidiaSmiPath" -ForegroundColor Red
    Write-Host "This optimization requires NVIDIA driver with nvidia-smi tool." -ForegroundColor Yellow
}

revert22H2:
$nvidiaSmiPath = 'C:\Program Files\NVIDIA Corporation\NVSMI\nvidia-smi.exe'

if (Test-Path $nvidiaSmiPath) {
    Write-Host "Found nvidia-smi.exe, reverting clock policy..." -ForegroundColor Green
    & $nvidiaSmiPath -rgc
    & $nvidiaSmiPath -rac
    & $nvidiaSmiPath -pm 0
